using System.Text.Json;
namespace RedTrace.Windows;
public sealed record ActivityEvent(string Id,DateTime Timestamp,string Phase,string Origin,string Tool,string Category,string Command,string Target,string Output,int? ExitCode,TimeSpan? Duration,string Raw);
public sealed class ActivityStore : IDisposable { readonly string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".redtrace","codex-events.jsonl");readonly Dictionary<string,ActivityEvent> starts=[];readonly List<ActivityEvent> events=[];long offset;string partial="";readonly System.Timers.Timer timer=new(125);public event Action? Changed;public IReadOnlyList<ActivityEvent> Events=>events;public ActivityStore(){timer.Elapsed+=(_,_)=>Read();timer.Start();}void Read(){try{if(!File.Exists(path))return;using var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite);if(f.Length<offset)offset=0;if(f.Length==offset)return;f.Position=offset;using var r=new StreamReader(f);var text=partial+r.ReadToEnd();offset=f.Length;var lines=text.Split('\n');partial=text.EndsWith('\n')?"":lines[^1];foreach(var line in lines.Take(text.EndsWith('\n')?lines.Length:lines.Length-1))Parse(line);}catch{}}void Parse(string line){try{using var d=JsonDocument.Parse(line);var o=d.RootElement;string Get(string n)=>o.TryGetProperty(n,out var x)?x.ToString():"";var tool=Get("tool_name");var cmd=Get("command");var target=Get("target");var id=Get("tool_use_id");if(string.IsNullOrEmpty(id))id=Get("session_id")+Get("turn_id")+tool+Guid.NewGuid();var now=DateTime.TryParse(Get("timestamp"),out var parsed)?parsed:DateTime.UtcNow;var e=new ActivityEvent(id,now,Get("phase"),Get("origin"),tool,Classify(tool,cmd),cmd,target,Get("output"),int.TryParse(Get("exit_code"),out var code)?code:null,null,line);if(e.Phase=="start"){starts[id]=e;return;}if(starts.Remove(id,out var s))e=e with {Duration=now-s.Timestamp,Command=string.IsNullOrEmpty(cmd)?s.Command:cmd,Target=string.IsNullOrEmpty(target)?s.Target:target};events.Add(e);if(events.Count>3000)events.RemoveRange(0,events.Count-3000);Changed?.Invoke();}catch{}}public static string Classify(string tool,string command){var x=(tool+" "+command).ToLowerInvariant();if(x.Contains("git "))return"git";if(x.Contains("build"))return"build";if(x.Contains("test"))return"test";if(x.Contains("rg ")||x.Contains("grep")||x.Contains("search"))return"search";if(x.Contains("read")||x.Contains("get-content")||x.Contains("cat "))return"read";if(x.Contains("write")||x.Contains("edit"))return"edit";if(x.Contains("curl")||x.Contains("wget")||x.Contains("invoke-webrequest"))return"network";return string.IsNullOrEmpty(command)?"tool":"command";}public void Dispose()=>timer.Dispose(); }
